"""Report regenerated from preserved summaries, including negative/partial attempts."""
import statistics,time,hashlib
from common import *
def fmt(r,digits=2):return 'unmeasured' if not r else '/'.join(f'{r[k]:.{digits}f}' for k in ['min','median','max'])
def med(r):return 'unknown' if not r else f"{r['median']:.2f}"
def main():
 elapsed=time.monotonic()-load(C/'clock.json')['start_monotonic'];selection=load(C/'models/selection.json') if (C/'models/selection.json').exists() else {};summary=load(C/'results/main-summary.json') if (C/'results/main-summary.json').exists() else [];pairs=load(C/'results/paired-blocks.json') if (C/'results/paired-blocks.json').exists() else [];attempts=load(C/'results/live-attempts.json') if (C/'results/live-attempts.json').exists() else [];metrics=load(C/'results/development-calibration-prediction-metrics.json') if (C/'results/development-calibration-prediction-metrics.json').exists() else [];held=load(C/'results/reserved-prediction-metrics.json') if (C/'results/reserved-prediction-metrics.json').exists() else [];offline=load(C/'results/offline-competition.json') if (C/'results/offline-competition.json').exists() else [];reserved=load(C/'results/offline-reserved.json') if (C/'results/offline-reserved.json').exists() else [];runtime=load(C/'builds/runtime-identity.json') if (C/'builds/runtime-identity.json').exists() else {}
 gains=[]
 for task in ['code-archive','math-inventory','text-websocket','mixed-chinook']:
  pp=[p for p in pairs if p['task']==task]
  if len(pp)==3 and all(p['full_reference_benefit'] and p['learned_time_saving_s']>0 and p['learned_wall_change_pct']<0 for p in pp) and statistics.median(p['learned_TG_change_pct'] for p in pp)>=3:gains.append(task)
 if len(gains)==4:conclusion='CAUSAL_VICTIM_GAIN_WITH_ORACLE_INCOMING'
 elif gains:conclusion='DOMAIN_SCOPED_CAUSAL_VICTIM_GAIN'
 elif not pairs and any((p/'episode.json').exists() and not load(p/'episode.json').get('valid') for p in (C/'raw').iterdir() if p.is_dir()):conclusion='INTEGRATION_OR_FIDELITY_BLOCKED'
 elif len(pairs)<12:conclusion='INCONCLUSIVE' if selection.get('promising',True) else 'NO_GAIN_IN_TESTED_CAUSAL_VICTIM_POLICIES'
 else:
  improved=sum((r['cpu_entries']+r['mapped_entries'])<(next(x for x in attempts if x['task']==r['task'] and x['block']==r['block'] and x['arm']=='REPLAY_CURRENT' and x['valid'])['cpu_entries']+next(x for x in attempts if x['task']==r['task'] and x['block']==r['block'] and x['arm']=='REPLAY_CURRENT' and x['valid'])['mapped_entries']) for r in attempts if r.get('valid') and r['arm']=='ORACLE_IN_LEARNED_VICTIM')
  conclusion='MECHANISM_IMPROVED_NO_CONFIRMED_LATENCY_GAIN' if improved else 'NO_GAIN_IN_TESTED_CAUSAL_VICTIM_POLICIES'
 save(C/'results/conclusion.json',{'primary':conclusion,'conditional_gain_tasks':gains,'valid_main':sum(r['valid'] for r in attempts),'main_attempts':len(attempts),'complete_blocks':len(pairs),'elapsed_s':elapsed,'criteria':'Descriptive confirmation requires three complete paired blocks, positive full reference each block, learned faster decode and wall in all three, median paired TG gain>=3%; not a significance test or universal claim. Scope selected all families before reserved evaluation.'})
 lines=['# Golden Swap Phase 1: oracle incoming and causal victim return risk','',f'**{conclusion}**','',f"Actual elapsed at report regeneration: **{elapsed/60:.2f} minutes**. Start {load(C/'clock.json')['start_utc']}; hard deadline {load(C/'clock.json')['deadline_utc']}. No deadline reset.",'',f"Completed: twelve source-level datasets; two bounded multi-horizon models; development/calibration policy competition; frozen finalist `{selection.get('policy','none')}` with guard threshold `{selection.get('threshold','none')}`; {sum(r['valid'] for r in attempts)}/{len(attempts)} valid main requests and {len(pairs)}/12 complete three-mode blocks. Integration/safety evidence is in tests and phase-a. Required unmeasured requests: {36-sum(r['valid'] for r in attempts)}.",'']
 if gains:lines += [f"Conditional gains meet the campaign's descriptive criterion on: {', '.join(gains)}. The finalist was frozen for all four families; task-specific specialization inferred from final results remains exploratory. One archive task does not establish all Python or agent work.",'']
 lines+=['## Measured replay results','', 'Values are min/median/max unless marked paired median. Replay-equivalent tok/s uses actual emitted tape tokens; WebSocket emits 1773. All four reserved profiles have 32768 configured context. Native decode time ends before final commit wait, copier drain/restoration and tape flushing. Initial tape/state attestation also lies outside native prefill/decode timers. Request wall includes prefill, initial attestation, online scorer/copies, final drain/restoration and flush; completion-inclusive wall is therefore required alongside TG. Startup/warmup/owned shutdown are separate.','', '| Task/profile | Mode | Valid/attempts | Replay-equivalent tok/s min/median/max | Paired decode-time change | Full-gain retention | Wall s | Local % | CPU/mapped entries | Copy GB | Reload/victim absence | Scorer/planner cost |','|---|---|---|---|---|---|---|---|---|---|---|---|']
 for s in summary:
  lines.append(f"| {s['task']}/{s['profile']} input{s['actual_input_tokens']} | {s['mode']} | {s['valid']}/{s['attempts']} | {fmt(s['tok_s'])} | {med(s.get('paired_decode_change_pct'))}% | {fmt(s.get('retention')) if s['mode']=='ORACLE_IN_LEARNED_VICTIM' else 'reference' if s['mode']=='ORACLE_FULL' else 'n/a'} | {fmt(s['wall_s'])} | {med(s['local_pct'])} | {med(s['cpu_entries'])}/{med(s['mapped_entries'])} | {med(s['copy_GB'])} | {med(s['reloads'])}/{med(s['victim_absent_entries'])} | feature{med(s['scorer_feature_ms'])}/score{med(s['scorer_model_ms'])}/selection{med(s['scorer_selection_ms'])}/planner{med(s['planner_ms'])} ms |")
 lines+=['','Scorer feature/model timers are contained inside candidate selection, which is contained inside planner; these overlapping timers must not be summed. Copy GB includes native/oracle completed published weight payload plus mandatory oracle restoration. All attempts, errors and telemetry remain in live-attempts JSON/CSV and raw logs. MTP demand conservation is separate; MTP dispatch subdivisions remain unknown.','', '## Paired block evidence','', '| Task/block | Current/full/learned decode s | Full saving s | Learned saving s | Paired learned TG % | Paired learned wall % | Retention | Stable denominator? |','|---|---|---|---|---|---|---|---|']
 for p in pairs:lines.append(f"| {p['task']}/{p['block']} | {p['current_decode_s']:.4f}/{p['full_decode_s']:.4f}/{p['learned_decode_s']:.4f} | {p['full_time_saving_s']:.4f} | {p['learned_time_saving_s']:.4f} | {p['learned_TG_change_pct']:.2f} | {p['learned_wall_change_pct']:.2f} | {'undefined' if p['retention'] is None else format(p['retention'],'.3f')} | {not p['retention_unstable']} |")
 lines+=['','Retention=(T_current-T_learned)/(T_current-T_full), computed within each block, never clamped. It is undefined for a nonpositive denominator and flagged unstable below 1% of current time. Full oracle is a feasible heuristic, not an optimal bound. Three repeated timings of one tape are not three independent source tasks.','']
 for s in summary:
  if s['mode']=='ORACLE_IN_LEARNED_VICTIM':lines.append(f"- {s['task']}: decode faster in {s.get('decode_faster_pairs',0)}/{s.get('paired_blocks',0)} pairs; wall faster in {s.get('wall_faster_pairs',0)}/{s.get('paired_blocks',0)}; paired TG min/median/max {fmt(s.get('paired_TG_change_pct'))}%; wall {fmt(s.get('paired_wall_change_pct'))}%.")
 lines+=['','## Prediction and frozen selection','', 'Training: development code-heg/math-rational/text-http/mixed-build. Operating point: calibration code-queue/math-sensor/text-tls/mixed-fields. Reserved: code-archive/math-inventory/text-websocket/mixed-chinook. Related source groups remain together and earlier exposure is retained. All twelve are single requests with tool_execution=false.','', 'Uniformly sample up to eight compatible native residents per layer every fourth main window, excluding declared full-current-window protection. Inclusion probability=min(8,N)/N; weight=1/k within a decision. This includes retained candidates rather than only native evictions. Native-policy resident population remains a covariate-selection limitation; simulated/live ownership follows each policy. Prefix-only features do not import policy-dependent native ages or eviction counts.','', 'Thirteen CPU features cover layer/device/byte class, prefix seen flag, last-use distance, fast/slow prefix EMA entries, prefix counts, last/mean gap and gap CV, and observed window count. Unknown pre-request recency is marked with seen=false. Complete native dynamic heat, queue fields and MTP subdivisions are omitted rather than zero-filled. Initial native heat is used only by the matched native-history control/fallback. Feature/scoring parity and suffix tests are in tests.','', 'Return labels use strictly later simultaneous batch demand and inclusive horizons1/4/16/64 main verify windows (48 routed-layer invocations/window). Positive requires an observed return by H; negative requires observation through H; otherwise mask=0. No lane ordering or finite-end negative is invented. These horizons differ from earlier decomposition H64 invocation units.','', '| Split/model/horizon | Tasks | Mean task AUC | Mean task Brier | Censored rows |','|---|---|---|---|---|']
 for split in ['development','calibration','reserved_evaluation']:
  for model in ['logistic','tree']:
   for h in [1,4,16,64]:
    rr=[r for r in metrics+held if r['split']==split and r['model']==model and r['horizon']==h]
    if rr:lines.append(f"| {split}/{model}/{h}windows | {len(rr)} | {statistics.mean(r['auc'] for r in rr if r['auc'] is not None):.4f} | {statistics.mean(r['brier'] for r in rr):.4f} | {sum(r['censored'] for r in rr)} |")
 lines+=['', 'Task-level calibration bins and task/family discrimination/support summaries, sampled rankings and learning curves are preserved. No random within-episode split establishes generalization. Two candidates: logistic C1 and32 depth3 boosting trees/head. No broad search or MLP. Frozen weights remain unchanged in live inference.','',f"Selection record: `{selection}`",'', 'The matched cheap native/history rule achieved a lower calibration proxy than the selected learned model. The learned finalist was selected among learned candidates to answer the predictor question; its offline promise is relative to replay-current, not proof of superiority to the cheap rules. No cheap-control live latency result is available in the main three-mode matrix.','', 'Victim rank minimizes p1+0.5p4+0.25p16+0.125p64. Common causal exchange guard requires the existing incoming16-window count to cover assumed staging/copy cost at160us net gain per routed entry plus p16-weighted prefix-rate victim loss. The160us figure is an assumed operating point, not an exclusive measuredCPU cost. A risk-only v1 caused excessive traffic; a40us v2 under-admitted and exposed repeated-scan overhead. Both negative versions remain under versions/. Same-event compatible selection now caches with ownership and prefix-history invalidation. The frozen guard also vetoes risk above the frozen threshold at the incoming demand interval; interval risk uses p1 conservatively through one window and linear interpolation toward p4 beyond it. This proxy treats near returns as costly and retains long-risk protection; it is not exact counterfactual regret or a measured latency model. Matched native/recency controls receive identical guard thresholds and physical scheduler. Incoming candidate order/E64/first-feasible protocol are fixed. No extra incoming ranker is added.','', 'Scores are CPU-only and cached per expert for at most one main window; a completed batch invalidates its layer. Current slot identity and full-window protection are rechecked at publication. NO_SWAP retains normal CPU/mapped expert computation. Invalid scores use causal native-history fallback; no victim-future fallback. No new allocator, lease, queue, GPU model buffers, extra experts or online weight fitting.','', '## Offline policy evidence','', 'The original recorded replay-current denominator and native slots are reconstructed exactly from issue/publication timestamps and validated against every routed entry. Transfer policies share initial state, slot classes, five charged spares and policy-specific ownership. The modeled main cadence0.57ms/invocation, MTP2.5ms/window, staging25GB/s, H2D13.2GB/s and publication45us are inherited assumptions. There is no exclusive CPU-latency model; modeled nonlocal demand/copy traffic is not measured TG or measured oracle-gain retention. No offline speed claim is made.','', '| Task/split | Policy/threshold | Nonlocal entries | Copy GB | Victim absence | Rejections | CPU evaluator wall s | Selection ms |','|---|---|---|---|---|---|---|---|']
 for r in offline+reserved:lines.append(f"| {r['task']}/{r['split']} | {r['policy']}/{r['threshold']} | {r['cpu']+r['mapped']} | {r['copied_bytes']/1e9:.3f} | {r.get('victim_absent_observations','unknown')} | {r.get('rejections','unknown')} | {r.get('evaluation_wall_s','n/a')} | {r.get('scorer_selection_ms','n/a')} |")
 lines+=['','## Fidelity, safety and physical costs','',f"Runtime identity: `{runtime}`.",'','Unchanged original binary SHA256 eca9d0d271340a114955d5af8038dbffa139ad096ef0d470bcfea9009d4f8d0d/source6f32ec070f23ced9f50e704d854d775da52591ab; model revision38bb39ee97821de2c9009abb7e93950eec396e66. Phase0 capture117bc89 and decompositionbbfea295 compatibility is checked, not assumed. Two RTX4090, K24, PCIe0.28, pool100us/15workers, MTP4/minp0.5, INT8KV/kv-resident32768, prefillauto and reuse/suffixOFF.','', 'Same48main routed layers/allthree byteclasses and five charged spares are used; replay-current retains normal capacity/adaptation. Immutable full-RAM backing and copy completion/publication ownership remain intact. Each arm uses a fresh server, saved64-token warmup, natural prefill and exact recorded initial state. Future tape/index RAM initialization is common setup and disclosed; no future expert weights are loaded during untimed setup. All online model/planning work and real copies remain charged. The experimental scorer remains disabled in normal launchers.','', 'Short-input QSA validates active min(n_kv,2051) width, preserving unused capacity. Final EOS can occur inside the last accepted window; emitted count and committed state count are separately checked. Live fidelity validates exact input/output IDs, window/MTP counts, native work FNV/SHA, QSA branch coverage, meaningful initial state sidecars and finite activation samples. Enforced output identity does not prove natural generation or quality. The inherited expert paths use CPU Q8_K versus GPU Q8_1 activation quantization and different summation order. Placement can change intermediate activations and pre-override native heads; these are sampled numerical diagnostics, not full tensor parity or natural-generation quality. Per-arm fidelity JSON preserves relative L2, maximum difference and first differing sampled component; forced work fingerprints and copied-byte/ownership checks are separate.','', 'Safety test logs retain invalid score fallback, NO_SWAP, protected victims, changed ownership, future suffix invariance, duplicate in-flight copies, real copied-byte checks across all classes/devices, late completion, spare reuse, cancellation/drain/restoration and next-request/shutdown behavior. Existing targeted native tests are reported with their actual results; historical full-suite environment failures are not represented as new passes.','', 'Per-arm raw telemetry includes CPU/steal and both GPU memory/utilization/power/clocks. No host settings changed; no favorable-run filtering, fourth unchanged attempt or steal correction. Counterbalancing reduces but does not eliminate VM drift. Local share, victim absence and overlapping CPU/GPU/planner times are not exclusive causal latency. Unknown rejection subreasons/MTP path subdivisions remain unknown.','', '## Protocol deviations, limitations and next experiment','', 'Dataset/state reconstruction smoke passed before the larger fit. The first compiled scorer/policy end-to-end smoke followed the larger bounded fit rather than preceding it; this order deviation is retained. No raw tape was recaptured. All held-out results and invalid attempts remain in the ledger. Source correctness repairs, if any, are versioned and old results preserved.','', 'One physical VM, three groups/family, previously exposed source groups, finite2048-token slices (WebSocket1773), no guard tail and no tool execution limit generality. The scope is oracle incoming plus causal victim ranking with oracle current-window safety; it is not a fully causal production scheduler or natural serving speedup. Full oracle may exploit finite tape ending and is not an optimal upper bound.','', 'Strongest next experiment: independent source-group tasks with a recorded guard tail and predeclared specialization, compare the frozen victim policy under the same oracle incoming/safety substrate while measuring scorer cache/selection overhead and completion-inclusive request wall. If ranking signal survives but latency does not, first test a bounded score-update/ranking-cost ablation without changing incoming ranking or physical capacity.','', '## Exact reproduction','', 'See reproduce.md for tested commands and identity checks. Dataset/model scripts operate on existing tapes and fixed source-level roles. Replay commands never update or rebuild the runtime, verify model/binary/checkpoint/config identities, use finite timeouts and stop only owned processes. Normal serving launchers remain unchanged.','',f'Primary research conclusion: **{conclusion}**.']
 (C/'report.md').write_text('\n'.join(lines)+'\n');print('REPORT REGENERATED',conclusion,flush=True)
